# This formula is regenerated by the ankra-cli release workflow from
# packaging/homebrew/ankra.rb.tmpl in ankraio/ankra-cli. Manual edits here
# will be overwritten on the next release; change the template instead.
#
# There is deliberately no `version` stanza: `brew audit` fails a tap whose
# declared version it can already scan from the stable URL (redundant_version),
# and every release URL below carries the tag. That is why the URLs interpolate
# nothing - the release workflow substitutes the version into them directly.
class Ankra < Formula
  desc "Command-line interface for the Ankra Kubernetes platform"
  homepage "https://ankra.io"
  license "Apache-2.0"

  livecheck do
    url :stable
    strategy :github_latest
  end

  on_macos do
    on_arm do
      url "https://github.com/ankraio/ankra-cli/releases/download/v0.83.0/ankra-cli-darwin-arm64"
      sha256 "e436cc26e2f8971edab6d99547e6ea3c4eab73c28da9172008977985832314ce"
    end
    on_intel do
      url "https://github.com/ankraio/ankra-cli/releases/download/v0.83.0/ankra-cli-darwin-amd64"
      sha256 "346fcf2522983e578324a994e3d9f3aa464b55945c94d17d9e6a17f3ae72b26a"
    end
  end

  on_linux do
    on_arm do
      url "https://github.com/ankraio/ankra-cli/releases/download/v0.83.0/ankra-cli-linux-arm64"
      sha256 "bb7107047009811ea5bdf1655c72970519ba1c84a146dddff6c63815c84fc684"
    end
    on_intel do
      url "https://github.com/ankraio/ankra-cli/releases/download/v0.83.0/ankra-cli-linux-amd64"
